class TestPoly(unittest.TestCase):
    def test_linear(self):
        # p(x) = 2x + 3
        self.assertAlmostEqual(poly([3, 2], 1.0), 5.0)

    def test_constant(self):
        # p(x) = 7
        self.assertAlmostEqual(poly([7], 10.0), 7.0)

    def test_quadratic(self):
        # p(x) = x^2 - 4
        self.assertAlmostEqual(poly([-4, 0, 1], 2.0), 0.0)

    def test_cubic(self):
        # p(x) = x^3 + 2x^2 + 3x + 4 at x = 2 => 8 + 8 + 6 + 4 = 26
        self.assertAlmostEqual(poly([4, 3, 2, 1], 2.0), 26.0)

    def test_negative_x(self):
        # p(x) = x^2 at x = -3 => 9
        self.assertAlmostEqual(poly([0, 0, 1], -3.0), 9.0)

    def test_zero_x(self):
        # p(x) = 5x^2 - 3x + 2 at x = 0 => 2
